export enum MusicPlayState {
    Idle,
    Loading,
    Playing,
    Paused
}

const FfiConverterTypeMusicPlayState = (() => {
    type TypeName = MusicPlayState;
    class FFIConverter extends AbstractFfiConverterByteArray<TypeName> {
        readFromCursor(c: Cursor): TypeName {
            switch (c.readI32()) {
                case 1: return MusicPlayState.Idle;
                case 2: return MusicPlayState.Loading;
                case 3: return MusicPlayState.Playing;
                case 4: return MusicPlayState.Paused;
                default: throw new UniffiInternalError.UnexpectedEnumCase();
            }
        }
        writeIntoCursor(value: TypeName, c: Cursor): void {
            switch (value) {
                case MusicPlayState.Idle: return c.writeI32(1);
                case MusicPlayState.Loading: return c.writeI32(2);
                case MusicPlayState.Playing: return c.writeI32(3);
                case MusicPlayState.Paused: return c.writeI32(4);
            }
        }
        allocationSize(value: TypeName): number {
            return 4;
        }
    }
    return new FFIConverter();
})();

